const int PACK = A0;
const int LOAD = 7;
const float CUT = 6.6;    // 3.3 V a cell
bool cut = false;

void setup() {
  pinMode(LOAD, OUTPUT);
  digitalWrite(LOAD, HIGH);
  Serial.begin(9600);
}

void loop() {
  float pack = analogRead(PACK) * 5.0 / 1023.0 * 3.0;
  Serial.print("pack ");
  Serial.println(pack, 1);
  if (!cut && pack < CUT) {
    cut = true;
    digitalWrite(LOAD, LOW);
    Serial.println("cut-off");
  }
  delay(250);
}

