const int PACK = A0;    // the pack through 20 kΩ / 10 kΩ: a third of it
const int LOAD = 7;     // HIGH: the motor's MOSFET is on

void setup() {
  pinMode(LOAD, OUTPUT);
  digitalWrite(LOAD, HIGH);
  Serial.begin(9600);
}

void loop() {
  float pack = analogRead(PACK) * 5.0 / 1023.0;   // this is the voltage at A0, not the pack
  Serial.print("pack ");
  Serial.println(pack, 1);
  // switch D7 off under 6.6 V and keep it off
  delay(250);
}

